 <?php $__env->startSection('title','Verifikasi Praktikum'); ?> <?php $__env->startSection('content'); ?><div class="container py-4"><h2 class="fw-bold">Verifikasi Pendaftaran Praktikum</h2><p class="text-secondary">Admin mengecek syarat dan menentukan kelas akhir. Mahasiswa dapat dipindahkan jika kelas pilihan penuh.</p><div class="vstack gap-3"><?php $__empty_1 = true; $__currentLoopData = $registrations; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $r): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); $__empty_1 = false; ?><div class="card border-0 shadow-sm"><div class="card-body"><div class="row g-3"><div class="col-lg-4"><h5><?php echo e($r->student->name); ?></h5><div>NPM: <?php echo e($r->student->npm); ?></div><div>Pilihan: <strong><?php echo e($r->preferredClass->course->name); ?> - <?php echo e($r->preferredClass->class_name); ?></strong></div><span class="badge text-bg-<?php echo e($r->status==='approved'?'success':($r->status==='rejected'?'danger':'warning')); ?> mt-2"><?php echo e($r->status); ?></span></div><div class="col-lg-4"><h6>Persyaratan</h6><?php $__currentLoopData = $r->submissions; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $s): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><div class="small mb-1"><?php echo e($s->requirement->title); ?> — <a target="_blank" href="<?php echo e(asset('storage/'.$s->file_path)); ?>">lihat file</a></div><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></div><div class="col-lg-4"><form method="POST" action="<?php echo e(route('admin.registrations.verify',$r)); ?>"><?php echo csrf_field(); ?> <?php echo method_field('PUT'); ?><label class="form-label">Kelas akhir</label><select class="form-select form-select-sm mb-2" name="final_class_id"><option value="">Pilih kelas</option><?php $__currentLoopData = $classes; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $c): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($c->id); ?>" <?php if(($r->final_class_id?:$r->practicum_class_id)==$c->id): echo 'selected'; endif; ?>><?php echo e($c->course->name); ?> - <?php echo e($c->class_name); ?> (<?php echo e($c->day); ?>)</option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select><textarea class="form-control form-control-sm mb-2" name="admin_note" placeholder="Catatan admin"><?php echo e($r->admin_note); ?></textarea><div class="d-flex gap-2"><button name="decision" value="approved" class="btn btn-success btn-sm">ACC</button><button name="decision" value="rejected" class="btn btn-outline-danger btn-sm">Tolak</button></div></form></div></div></div></div><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_1): ?><div class="alert alert-light">Belum ada pendaftaran.</div><?php endif; ?></div></div><?php $__env->stopSection(); ?>
